-- Owner-authorized rebinding, 2026-11-02 (Noam). No hint text changes; no model calls.
-- 401 grade 7-9 worksheet PDFs were republished on Wix with their final-answers pages
-- appended. Each new PDF repeats the old PDF's question pages exactly (verified page by
-- page, text and drawings), so every hint bound to an old PDF is rebound to its new PDF.
-- Only source_pdf_hash changes; hints, native bindings, status, source and source_id stay.
-- Idempotent: a no-op when the final bank is already present.
begin;
lock table public.noam_ramzi_hints in share row exclusive mode;
do $rebind$
declare bank_count bigint; core_sha text; affected bigint;
begin
  select count(*),encode(sha256(convert_to(string_agg(concat_ws(chr(31),exercise_id,hint_1,hint_2,hint_3,source_pdf_hash,coalesce(source_native_sha256,''),status,source,source_id),chr(30)order by exercise_id collate "C"),'UTF8')),'hex') into bank_count,core_sha from public.noam_ramzi_hints;
  if bank_count=31670 and core_sha='a14e5ecc87fec7af296135dfe55d1298e9d987b50b7dac0d88dc14a2fd042033' then return; end if;
  if bank_count<>31670 or core_sha is distinct from '608051e56ac7fe7cf286651ff1c63a55b9c736ba4f92ec56e8a5685eec6f484e' then raise exception 'Prepared hint bank changed; refusing rebinding'; end if;
  create temporary table rebind_map(old_pdf text primary key,new_pdf text not null,expected bigint not null) on commit drop;
  update public.noam_ramzi_hints h set source_pdf_hash=m.new_pdf from rebind_map m where h.source_pdf_hash=m.old_pdf;
  get diagnostics affected=row_count;
  if affected<>30229 then raise exception 'Expected 30229 rebound rows, got %',affected; end if;
  select count(*),encode(sha256(convert_to(string_agg(concat_ws(chr(31),exercise_id,hint_1,hint_2,hint_3,source_pdf_hash,coalesce(source_native_sha256,''),status,source,source_id),chr(30)order by exercise_id collate "C"),'UTF8')),'hex') into bank_count,core_sha from public.noam_ramzi_hints;
  if bank_count<>31670 or core_sha is distinct from 'a14e5ecc87fec7af296135dfe55d1298e9d987b50b7dac0d88dc14a2fd042033' then raise exception 'Rebinding verification failed'; end if;
end;
$rebind$;
commit;
